def _service_observable_out_box(self, limit: int=None) -> int:
    msg_count = 0
    while True:
        if limit and msg_count >= limit:
            break
        msg = self._observable.get_output()
        if not msg:
            break
        msg_count += 1
        (msg, observer_ids) = msg
        self.sendToNodes(msg, observer_ids)
    return msg_count

