def apply_T12(word):
    WORD = word
    offset = 0
    for vv in new_vv(WORD):
        seq = vv.group(1)
        if not is_diphthong(seq) and (not is_long(seq)):
            i = vv.start(1) + 1 + offset
            WORD = WORD[:i] + '.' + WORD[i:]
            offset += 1
    RULE = ' T2' if word != WORD else ''
    return (WORD, RULE)

