def in_ellipsoid(x, A, c):
    if x.ndim == 1:
        y = c - x
        return np.einsum('j,jl,l', y, np.linalg.inv(A), y) <= 1
    else:
        y = c[np.newaxis, :] - x
        return np.einsum('ij,jl,il->i', y, np.linalg.inv(A), y) <= 1

