            s.root.append(imp)
    return self

def prune(A, threshold):
    if isinstance(A, Poly):
        B = A.A.copy()
        for key in A.keys:
            values = B[key].copy()
            values[numpy.abs(values) < threshold] = 0.0
            B[key] = values
        return Poly(B, A.dim, A.shape, A.dtype)
    A = A.copy()
    A[numpy.abs(A) < threshold] = 0.0
    return A

