def new_id(self):
    with self._lock:
        curr = self._residue
        self._residue += 1
        if self._residue >= BLOCK_SIZE:
            increment = self._atomic_long.get_and_increment().result()
            self._local = increment
            self._residue = 0
            return self.new_id()
        return self._local * BLOCK_SIZE + curr

