def connected_component(self, ident):
    ident = normalize_ident(ident)
    done = set()
    todo = set([ident])
    labels = set()
    while todo:
        ident = todo.pop()
        done.add(ident)
        for label in self.directly_connected(ident):
            if label.value != CorefValue.Positive:
                continue
            (ident1, ident2) = idents_from_label(label, subtopic=ident_has_subtopic(ident))
            if ident1 not in done:
                todo.add(ident1)
            if ident2 not in done:
                todo.add(ident2)
            if label not in labels:
                labels.add(label)
                yield label

def negative_directional_movement(high_data, low_data):
