def multi_replace(original, pattens, delim='|,'):
    if not original:
        return ''
    if not delim or len(delim) != 2:
        delim = '|,'
    (level0, level1) = (delim[0], delim[1])
    for re_pair in pattens.split(level0):
        (_f, _to) = (re_pair, '')
        re_pair = re_pair.split(level1)
        if len(re_pair) == 2:
            (_f, _to) = re_pair
        original = original.replace(_f, _to)
    return original

