def interact(self):
    if sys.platform == 'win32':
        self.mt_interact()
        return
    while True:
        (rfd, wfd, xfd) = select.select([self, sys.stdin], [], [])
        if self in rfd:
            try:
                text = self.read_eager()
            except EOFError:
                print('*** Connection closed by remote host ***')
                break
            if text:
                self.stdout.write(text)
                self.stdout.flush()
        if sys.stdin in rfd:
            line = sys.stdin.readline()
            if not line:
                break
            self.write(line)

