    if not inferred:
        raise exceptions.InferenceError(node=self, caller=caller, context=context)

def get_consumed_write_units_percent(table_name, lookback_window_start=15, lookback_period=5):
    try:
        metrics = __get_aws_metric(table_name, lookback_window_start, lookback_period, 'ConsumedWriteCapacityUnits')
    except BotoServerError:
        raise
    if metrics:
        lookback_seconds = lookback_period * 60
        consumed_write_units = float(metrics[0]['Sum']) / float(lookback_seconds)
    else:
        consumed_write_units = 0
    try:
        table_write_units = dynamodb.get_provisioned_table_write_units(table_name)
        consumed_write_units_percent = float(consumed_write_units) / float(table_write_units) * 100
    except JSONResponseError:
        raise
    logger.info('{0} - Consumed write units: {1:.2f}%'.format(table_name, consumed_write_units_percent))
    return consumed_write_units_percent

def unpackbools(integers, dtype='L'):
    atoms = ATOMS[dtype]
    for chunk in integers:
        for a in atoms:
            yield (not not chunk & a)

def add_child(self, child):
    child_id = getattr(child, 'id', None)
    if child_id:
        if not hasattr(self, 'children'):
            self.children = {}
        if child_id not in self.children:
            self.children[child_id] = child

def _parse_cfg_linters(self):
    user_value = self._config.get('linters', '')
    for line in user_value.splitlines():
        yield from self._parse_linters_line(line)

def list(path, ext=None, start=None, stop=None, recursive=False):
    files = listflat(path, ext) if not recursive else listrecursive(path, ext)
    if len(files) < 1:
        raise FileNotFoundError('Cannot find files of type "%s" in %s' % (ext if ext else '*', path))
    files = select(files, start, stop)
    return files

def update(dest, defaults, merge_lists=True, in_place=True):
    if in_place:
        nodes = dest
    else:
        nodes = deepcopy(dest)
    for (node_name, node_vars) in nodes.items():
        defaults_vars = deepcopy(defaults)
        node_vars = merge(defaults_vars, node_vars, merge_lists=merge_lists)
        nodes[node_name] = node_vars
    return nodes

def get_user_submissions(self, task):
    if not self._user_manager.session_logged_in():
        raise Exception('A user must be logged in to get his submissions')
    cursor = self._database.submissions.find({'username': self._user_manager.session_username(), 'taskid': task.get_id(), 'courseid': task.get_course_id()})
    cursor.sort([('submitted_on', -1)])
    return list(cursor)

def get_filter_kwargs(self):
    if self.is_valid():
        filter_kwargs = {}
        for field in self.get_filter_fields():
            empty_values = EMPTY_VALUES
            if hasattr(self.fields[field], 'empty_values'):
                empty_values = self.fields[field].empty_values
            value = self.cleaned_data.get(field)
            if not value in empty_values:
                if self.search_fields and field in self.search_fields:
                    filter_kwargs['%s__icontains' % field] = value
                else:
                    filter_kwargs[field] = value
        return filter_kwargs
    else:
        return {}

