def choose(n, k):
    if 0 <= k <= n:
        ntok = 1
        ktok = 1
        for t in xrange(1, min(k, n - k) + 1):
            ntok *= n
            ktok *= t
            n -= 1
        return ntok // ktok
    else:
        return 0

def assemble_flash_code(self, asm):
    stream = StringIO(asm)
    worker = assembler.Assembler(self.processor, stream)
    try:
        result = worker.assemble()
    except BaseException as e:
        return (e, None)
    self.flash.program(result)
    return (None, result)

def set_bar(self, bar, value):
    if bar < 0 or bar > 23:
        return
    c = (bar if bar < 12 else bar - 12) // 4
    a = bar % 4
    if bar >= 12:
        a += 4
    self.set_led(c * 16 + a + 8, 1 if value & GREEN > 0 else 0)
    self.set_led(c * 16 + a, 1 if value & RED > 0 else 0)

def read(self, n=None):
    response = ''
    while n is None or n > 0:
        c = self.stream.read(1)
        if c == '':
            break
        elif c == '<':
            c += self.stream.read(1)
            if c == '<?':
                while True:
                    q = self.stream.read(1)
                    if q == '>':
                        break
            else:
                response += c
                if n is not None:
                    n -= len(c)
        else:
            response += c
            if n is not None:
                n -= 1
    return response

def _get_device_methods(self, device):
    if device.is_filesystem:
        if device.is_mounted:
            if self._mounter._browser:
                yield 'browse'
            if self._mounter._terminal:
                yield 'terminal'
            yield 'unmount'
        else:
            yield 'mount'
    elif device.is_crypto:
        if device.is_unlocked:
            yield 'lock'
        else:
            yield 'unlock'
        cache = self._mounter._cache
        if cache and device in cache:
            yield 'forget_password'
    if device.is_ejectable and device.has_media:
        yield 'eject'
    if device.is_detachable:
        yield 'detach'
    if device.is_loop:
        yield 'delete'
